import { Utils } from '../lib/utils.js';
import { Strings } from '../lib/strings.js';
import { Tool } from './tool.js';
import { Input, PromptOptions } from '../lib/inputManager.js';
import { Logging } from '../lib/logging.js';
import { Point } from '../entities/point.js';
import { AddState } from '../lib/stateManager.js';

import { DesignCore } from '../designCore.js';
import { RubberBand } from '../lib/auxiliary/rubberBand.js';

/**
 * Copy Command Class
 * @extends Tool
 */
export class Copy extends Tool {
  static type = 'Copy';

  /** Create a Copy command */
  constructor() {
    super();
  }

  /**
   * Register the command
   * @return {Object}
   * command = name of the command
   * shortcut = shortcut for the command
   * type = type to group command in toolbars (omitted if not shown)
   */
  static register() {
    const command = { command: 'Copy', shortcut: 'CO', type: 'Tool' };
    return command;
  }

  /**
   * Execute method
   * executes the workflow, requesting input required to perform the command
   */
  async execute() {
    try {
      const op = new PromptOptions(Strings.Input.SELECTIONSET, [Input.Type.SELECTIONSET]);

      if (!DesignCore.Scene.selectionManager.selectionSet.selectionSet.length) {
        await DesignCore.Scene.inputManager.requestInput(op);
      }

      const op2 = new PromptOptions(Strings.Input.BASEPOINT, [Input.Type.POINT]);
      const pt1 = await DesignCore.Scene.inputManager.requestInput(op2);
      if (pt1 === undefined) return;
      this.points.push(pt1);

      const op3 = new PromptOptions(Strings.Input.DESTINATION, [Input.Type.POINT, Input.Type.DYNAMIC]);
      while (true) {
        // Reset to just the base point
        this.points = [this.points[0]];

        // Anchor inputPoint to the base point so DYNAMIC (distance) input always
        // projects relative to it, not relative to the last copied position.
        DesignCore.Scene.inputManager.inputPoint = this.points[0];

        const pt2 = await DesignCore.Scene.inputManager.requestInput(op3);
        if (pt2 === undefined) break;
        this.points[1] = pt2;
        DesignCore.Scene.inputManager.actionCommand();
      }

      DesignCore.Scene.inputManager.executeCommand();
    } catch (err) {
      Logging.instance.error(`${this.type} - ${err}`);
    }
  }

  /**
   * Preview the command during execution
   */
  preview() {
    if (this.points.length >= 1) {
      const mousePoint = DesignCore.Mouse.pointOnScene();

      // Draw a rubber-band line from base point to mouse
      DesignCore.Scene.auxiliaryEntities.add(new RubberBand([this.points.at(-1), mousePoint]));

      const delta = mousePoint.subtract(this.lastMousePoint || this.points[0]);
      this.lastMousePoint = mousePoint;

      for (let i = 0; i < DesignCore.Scene.selectionManager.selectedEntities.length; i++) {
        const entity = DesignCore.Scene.selectionManager.selectedEntities[i];
        const offsetPoints = entity.points.map((p) => new Point(p.x, p.y, p.bulge, p.sequence).add(delta));
        entity.setProperty('points', offsetPoints);
      }
    }
  }

  /**
   * Perform the command
   */
  action() {
    // points[1] is cleared before each destination prompt
    // executeCommand() calls action() - guard on missing points and duplication
    if (!this.points[1]) return;
    const delta = this.points[1].subtract(this.points[0]);
    const stateChanges = [];

    for (let i = 0; i < DesignCore.Scene.selectionManager.selectionSet.selectionSet.length; i++) {
      const copyOfEntity = Utils.cloneObject(DesignCore.Scene.entities.get(DesignCore.Scene.selectionManager.selectionSet.selectionSet[i]));
      const offsetPoints = copyOfEntity.points.map((p) => new Point(p.x, p.y, p.bulge, p.sequence).add(delta));
      copyOfEntity.setProperty('points', offsetPoints);
      const stateChange = new AddState(copyOfEntity);
      stateChanges.push(stateChange);
    }

    DesignCore.Scene.commit(stateChanges);
  };
}
