import { Tool } from './tool.js';
import { Input, PromptOptions } from '../lib/inputManager.js';
import { Strings } from '../lib/strings.js';
import { Logging } from '../lib/logging.js';
import { Point } from '../entities/point.js';

import { DesignCore } from '../designCore.js';

/**
 * WindowPick Command Class
 * Internal tool used to interactively pick two corner points defining a rectangular window (e.g. for the plot window area).
 * Not shown in any toolbar; invoked programmatically.
 * @extends Tool
 */
export class WindowPick extends Tool {
  static type = 'WindowPick';

  /** Create a WindowPick command */
  constructor() {
    super();
  }

  /**
   * Register the command
   * @return {Object}
   * command = name of the command
   */
  static register() {
    const command = { command: 'WindowPick' };
    return command;
  }

  /**
   * Execute method
   * requests the two corner points defining the plot window
   */
  async execute() {
    try {
      const op1 = new PromptOptions(Strings.Input.FIRSTCORNER, [Input.Type.POINT]);
      const pt1 = await DesignCore.Scene.inputManager.requestInput(op1);
      if (pt1 === undefined) return;
      this.points.push(pt1);

      const op2 = new PromptOptions(Strings.Input.SECONDCORNER, [Input.Type.POINT]);
      const pt2 = await DesignCore.Scene.inputManager.requestInput(op2);
      if (pt2 === undefined) return;
      this.points.push(pt2);

      DesignCore.Scene.inputManager.executeCommand();
    } catch (err) {
      Logging.instance.error(`${this.type} - ${err}`);
    }
  }

  /**
   * Preview the command during execution
   */
  preview() {
    if (this.points.length === 1) {
      const mousePoint = DesignCore.Mouse.pointOnScene();
      const p1 = this.points[0];
      const p2 = mousePoint;

      const points = [
        new Point(p1.x, p1.y),
        new Point(p2.x, p1.y),
        new Point(p2.x, p2.y),
        new Point(p1.x, p2.y),
        new Point(p1.x, p1.y),
      ];

      DesignCore.Scene.previewEntities.create('Polyline', { points: points });
    }
  }
}
