import { DimensionBase } from './dimensionBase.js';
import { AlignedDimension } from './alignedDimension.js';
import { DiametricDimension } from './diametricDimension.js';
import { AngularDimension } from './angularDimension.js';
import { RadialDimension } from './radialDimension.js';
import { RotatedDimension } from './rotatedDimension.js';

import { Arc } from '../entities/arc.js';
import { Circle } from '../entities/circle.js';
import { Line } from '../entities/line.js';
import { PolylineBase } from '../entities/polylineBase.js';
import { Point } from '../entities/point.js';

import { Strings } from '../lib/strings.js';
import { Input, PromptOptions } from '../lib/inputManager.js';
import { Logging } from '../lib/logging.js';
import { Intersection } from '../lib/intersect.js';

import { DesignCore } from '../designCore.js';
import { Property } from '../properties/property.js';
import { SingleSelection } from '../lib/selectionManager.js';
import { Utils } from '../lib/utils.js';
import { DimType } from '../properties/dimType.js';

/**
 * Dimension Entity Class
 * @extends DimensionBase
 */
export class Dimension extends DimensionBase {
  /**
   * Create a Dimension
   * @param {Array} data
   */
  constructor(data) {
    super(data);

    // map dimensions type to the class name — non-enumerable: internal workflow state
    Object.defineProperty(this, 'dimensionMap', {
      value: {
        0: RotatedDimension,
        1: AlignedDimension,
        2: AngularDimension,
        3: DiametricDimension,
        4: RadialDimension,
        5: null, // 5 = Angular 3 point;
        6: null, // 6 = Ordinate;
      },
      writable: true,
    });

    Object.defineProperty(this, 'selectedEntities', {
      value: [],
      writable: true,
    });

    if (data) {
      const DimensionType = this.dimensionMap[DimType.getBaseType(this.dimType.getBaseDimType())];

      if (!DimensionType) {
        // dimType 5 (Angular 3 point) and 6 (Ordinate) are valid DXF types but not yet implemented
        throw new Error(`${this.type} - ${Strings.Error.INVALIDTYPE}: ${this.dimType.getBaseDimType()}`);
      }

      const entity = new DimensionType(data);

      // find the block linked to this dimension
      const linkedBlockIndex = DesignCore.Scene.entities.find('BLOCK', 'name', data[2]);

      if (linkedBlockIndex.length) {
        // remove the block from the scene, dimensions manage their block internally
        DesignCore.Scene.entities.remove(linkedBlockIndex[0]);
      }

      return entity;
    }
  }

  /**
   * Register the command
   * @return {Object}
   * command = name of the command
   * shortcut = shortcut for the command
   * type = type to group command in toolbars (omitted if not shown)
   */
  static register() {
    const command = { command: 'Dimension', shortcut: 'DIM' };
    return command;
  }

  /**
   * Execute method
   * executes the workflow, requesting input required to create an entity
   */
  async execute() {
    try {
      let inputValid = false;
      this.setProperty(Property.Names.DIMENSIONSTYLE, DesignCore.DimStyleManager.getCstyle());

      while (!inputValid) {
        DesignCore.Scene.selectionManager.reset();
        const options = new PromptOptions(`${Strings.Input.START} ${Strings.Strings.OR} ${Strings.Input.SELECT}`, [Input.Type.POINT, Input.Type.SINGLESELECTION]);
        const input1 = await DesignCore.Scene.inputManager.requestInput(options);
        if (input1 === undefined) return;

        if (input1 instanceof Point) {
          inputValid = true;
          this.dimType.setDimType(1);
          // select a second point to define the dimension
          const op1 = new PromptOptions(Strings.Input.END, [Input.Type.POINT]);
          // avoid polar/ortho tracking a line from the first point while picking the second
          DesignCore.Scene.inputManager.inputPoint = null;
          const pt14 = await DesignCore.Scene.inputManager.requestInput(op1);
          if (pt14 === undefined) return;
          // Create a temporary line using the selected points
          const tempLine = new Line({ points: [input1, pt14] });
          this.selectedEntities.push(tempLine);
        }

        if (input1 instanceof SingleSelection) {
          const selectedEntity = DesignCore.Scene.entities.get(input1.selectedEntityIndex);

          // check the selected entity is supported
          if ([Line, Circle, Arc, PolylineBase].some((entity) => selectedEntity instanceof entity)) {
            // set the dimension type
            if (selectedEntity instanceof Line) {
              this.dimType.setDimType(1);
              this.selectedEntities.push(selectedEntity);
              inputValid = true;
            }

            if (selectedEntity instanceof Circle) {
              this.dimType.setDimType(3);
              this.selectedEntities.push(selectedEntity);
              inputValid = true;
            }

            if (selectedEntity instanceof Arc) {
              this.dimType.setDimType(4);
              this.selectedEntities.push(selectedEntity);
              inputValid = true;
            }

            if (selectedEntity instanceof PolylineBase) {
              // get the segment closest to the mouse point
              const segment = selectedEntity.getClosestSegment(input1.selectedPoint);

              if (segment instanceof Line) {
                this.dimType.setDimType(1);
                this.selectedEntities.push(segment);
                inputValid = true;
              }

              if (segment instanceof Arc) {
                this.dimType.setDimType(4);
                this.selectedEntities.push(segment);
                inputValid = true;
              }
            }
          } else {
            const msg = `${this.type} - ${Strings.Error.INVALIDTYPE}: ${selectedEntity.type}`;
            DesignCore.Core.notify(msg);
            DesignCore.Scene.selectionManager.reset();
          }
        }
      }

      // select a second line to make a angular dimension or a point to position the dimension text
      // loop until this.points contains a point with sequence 11 i.e. a text position
      while (!this.points.some((point) => point.sequence === 11)) {
        // default prompt: select a location for the text position
        let op2 = new PromptOptions(Strings.Input.DIMENSION, [Input.Type.POINT]);

        // Angular dimension prompt: select a second line for an angular dimension or location for the text position
        if ((this.selectedEntities[0] instanceof Line) && this.selectedEntities.length < 2) {
          op2 = new PromptOptions(`${Strings.Input.DIMENSION} or ${Strings.Input.SELECT}`, [Input.Type.POINT, Input.Type.SINGLESELECTION]);
        }

        // diametric prompt: select radial or diametric type dimension or location for the the text position
        if (this.selectedEntities[0] instanceof Circle) {
          const options = this.dimType.getBaseDimType() === 3 ? ['Radius'] : ['Diameter'];
          op2 = new PromptOptions(`${Strings.Input.DIMENSION}`, [Input.Type.POINT], options);
        }

        // avoid polar/ortho tracking a line from the last defining point while placing the dimension
        DesignCore.Scene.inputManager.inputPoint = null;
        const input2 = await DesignCore.Scene.inputManager.requestInput(op2);
        if (input2 === undefined) return;

        if (Input.getType(input2) === Input.Type.POINT) {
          const Pt11 = input2;

          // if selected entities are available, get the points from the selected entities
          // dimensions can be created from point selection only, therefore selected entities may not be available
          if (this.selectedEntities.length) {
            // for linear dimensions, determine if aligned or rotated based on mouse position
            if (this.dimType.getBaseDimType() === 0 || this.dimType.getBaseDimType() === 1) {
              const Pt13 = this.selectedEntities[0].points[0];
              const Pt14 = this.selectedEntities[0].points[1];
              const linearDimTypeNumber = this.getLinearDimensionType(Pt13, Pt14, Pt11);
              this.dimType.setDimType(linearDimTypeNumber);

              // Rotated dimensions use a fixed angle - choose horizontal or vertical based on the pick point
              if (linearDimTypeNumber === 0) {
                this.setProperty(Property.Names.LINEARDIMANGLE, this.getRotatedDimensionAngle(Pt13, Pt14, Pt11));
              }
            }

            const dimensionType = this.dimensionMap[this.dimType.getBaseDimType()]; // TODO: use this.dimensionMap.name?
            const angle = this.getProperty(Property.Names.LINEARDIMANGLE);
            this.points.push(...dimensionType.getPointsFromSelection(this.selectedEntities, Pt11, angle));
          }
        }

        if (Input.getType(input2) === Input.Type.STRING) {
          // options are converted to input in the prompt options class
          if (input2 === 'Diameter') {
            this.dimType.setDimType(3);
          }

          if (input2 === 'Radius') {
            this.dimType.setDimType(4);
          }
        }

        if (Input.getType(input2) === Input.Type.SINGLESELECTION) {
          let selectedEntity2 = DesignCore.Scene.entities.get(input2.selectedEntityIndex);
          if ([Line, PolylineBase].some((entity) => selectedEntity2 instanceof entity)) {
            // if a polyline is selected, get the segment closest to the mouse point
            if (selectedEntity2 instanceof PolylineBase) {
              // get the segment closest to the mouse point
              const segment = selectedEntity2.getClosestSegment(input2.selectedPoint);

              if (segment instanceof Line) {
                selectedEntity2 = segment;
              }
            }
            // Check lines intersect
            const line1 = { start: this.selectedEntities[0].points[0], end: this.selectedEntities[0].points[1] };
            const line2 = { start: selectedEntity2.points[0], end: selectedEntity2.points[1] };

            // Check the lines are not parallel - Can't dimension parallel lines
            const lineOneSlope = (line1.end.y - line1.start.y) / (line1.end.x - line1.start.x);
            const lineTwoSlope = (line2.end.y - line2.start.y) / (line2.end.x - line2.start.x);

            if (Utils.round(lineOneSlope) !== Utils.round(lineTwoSlope)) {
              const intersect = Intersection.intersectSegmentSegment(line1.start, line1.end, line2.start, line2.end, false, true);
              if (intersect.points.length >= 1) {
              // add line to selection
                this.selectedEntities.push(selectedEntity2);
                // Two lines selected - switch to angular dimension
                this.dimType.setDimType(2);
              }
            } else {
              const msg = `${this.type} - ${Strings.Error.SELECTION}: ${Strings.Error.PARALLELLINES}`;
              DesignCore.Core.notify(msg);
              DesignCore.Scene.selectionManager.removeLastSelection();
            }
          } else {
            const msg = `${this.type} - ${Strings.Error.INVALIDTYPE}: ${selectedEntity2.type}`;
            DesignCore.Core.notify(msg);
            DesignCore.Scene.selectionManager.reset();
          }
        }
      }

      // Dimension is a router entity with no buildDimension() of its own -
      // commit an instance of the resolved subtype (e.g. RotatedDimension), not this
      const DimensionType = this.dimensionMap[this.dimType.getBaseDimType()];
      const entity = new DimensionType({
        points: this.points,
        dimensionStyle: this.getProperty(Property.Names.DIMENSIONSTYLE),
        linearDimAngle: this.getProperty(Property.Names.LINEARDIMANGLE),
      });
      DesignCore.Scene.inputManager.executeCommand(entity);
    } catch (err) {
      Logging.instance.error(`${this.type} - ${err}`);
    }
  }

  /**
   * Determine if linear dimension is aligned or rotated
   * @param {Point} Pt13 - start point
   * @param {Point} Pt14 - end point
   * @param {Point} Pt11 - text position
   * @return {number} 0 = rotated, 1 = aligned
   */
  getLinearDimensionType(Pt13, Pt14, Pt11) {
    // generate the x and y delta values
    const dx = Pt14.x - Pt13.x;
    const dy = Pt14.y - Pt13.y;

    const pntPerp = Pt11.perpendicular(Pt13, Pt14);
    const isAligned = pntPerp.isOnLine(Pt13, Pt14);

    if (!isAligned || Utils.round(dx) === 0 || Utils.round(dy) === 0) {
      // Rotated dimension
      return 0;
    } else {
      // Aligned dimension
      return 1;
    }
  }

  /**
   * Determine the fixed dimension line angle for a Rotated dimension (horizontal or vertical)
   * @param {Point} Pt13 - start point
   * @param {Point} Pt14 - end point
   * @param {Point} Pt11 - pick point used to choose the axis
   * @return {number} angle in degrees - 0 = horizontal, 90 = vertical
   */
  getRotatedDimensionAngle(Pt13, Pt14, Pt11) {
    const dx = Pt14.x - Pt13.x;
    const dy = Pt14.y - Pt13.y;

    // axis-aligned edges only have one non-degenerate orientation
    if (Utils.round(dx) === 0) return 90;
    if (Utils.round(dy) === 0) return 0;

    // Diagonal edge: pick the axis the pick point deviates from the edge the most along
    const iX = (Math.abs(Pt11.x - Pt13.x) + Math.abs(Pt14.x - Pt11.x)) - Math.abs(dx);
    const iY = (Math.abs(Pt11.y - Pt13.y) + Math.abs(Pt14.y - Pt11.y)) - Math.abs(dy);

    return iX >= iY ? 90 : 0;
  }

  /**
   * Preview the entity during creation
   */
  preview() {
    if (this.selectedEntities.length) {
      let dimTypeNumber = this.dimType.getBaseDimType();

      const Pt11 = DesignCore.Mouse.pointOnScene();
      Pt11.sequence = 11;

      let angle;
      if (dimTypeNumber === 0 || dimTypeNumber === 1) {
        // for linear dimensions, determine if aligned or rotated based on mouse position
        const Pt13 = this.selectedEntities[0].points[0];
        const Pt14 = this.selectedEntities[0].points[1];
        dimTypeNumber = this.getLinearDimensionType(Pt13, Pt14, Pt11);

        // Rotated dimensions use a fixed angle - choose horizontal or vertical based on the pick point
        if (dimTypeNumber === 0) {
          angle = this.getRotatedDimensionAngle(Pt13, Pt14, Pt11);
        }
      }
      // get the dimension class
      const dimensionType = this.dimensionMap[dimTypeNumber];
      // get the dimension type as a string
      const dimensionTypeString = dimensionType.register().command;
      // get the points for the dimension
      const points = dimensionType.getPointsFromSelection(this.selectedEntities, Pt11, angle);
      // create the temporary dimension
      DesignCore.Scene.previewEntities.create(dimensionTypeString, { points: points, dimensionStyle: this.getProperty(Property.Names.DIMENSIONSTYLE), linearDimAngle: angle });
    }
  }
}
